package quarantine

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"io"

	"github.com/timreynolds/custodian/internal/domain"
	"github.com/timreynolds/custodian/internal/git/checkout"
)

// CleanPackOptions configures optional pack-objects flags when repacking quarantined objects for upstream.
type CleanPackOptions struct {
	UseOfsDelta bool
}

// CleanPackStats describes the streamed clean packfile generated by BuildCleanPack.
type CleanPackStats struct {
	BytesWritten int64  `json:"bytes_written"`
	PackSHA256   string `json:"pack_sha256"`
	HasObjects   bool   `json:"has_objects"`
}

// BuildCleanPack streams a freshly packed, verified Git packfile containing strictly the
// validated reachable objects for res.RefUpdates into dst. Pure deletion pushes emit 0 bytes.
func BuildCleanPack(ctx context.Context, res *UnpackResult, dst io.Writer, opts ...CleanPackOptions) (CleanPackStats, error) {
	if res == nil {
		return CleanPackStats{}, domain.BadRequest("INVALID_UNPACK_RESULT", "unpack result must not be nil")
	}
	if dst == nil {
		return CleanPackStats{}, domain.BadRequest("INVALID_DESTINATION_WRITER", "destination writer must not be nil")
	}
	if ctx == nil {
		ctx = context.Background()
	}

	res.mu.Lock()
	defer res.mu.Unlock()

	if res.closed || res.RepoDir == "" {
		return CleanPackStats{}, domain.BadRequest("QUARANTINE_CLOSED", "quarantine unpack result is closed")
	}

	if !res.NeedsPack() {
		return CleanPackStats{
			BytesWritten: 0,
			PackSHA256:   domain.SHA256Hex(nil),
			HasObjects:   false,
		}, nil
	}

	var opt CleanPackOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	if res.timeout > 0 {
		if _, hasDeadline := ctx.Deadline(); !hasDeadline {
			var cancel context.CancelFunc
			ctx, cancel = context.WithTimeout(ctx, res.timeout)
			defer cancel()
		}
	}

	var stdinBuf bytes.Buffer
	for _, oid := range collectUniqueNonZeroNewOIDs(res.RefUpdates) {
		stdinBuf.WriteString(oid)
		stdinBuf.WriteByte('\n')
	}
	for _, ex := range res.excludeOIDs {
		stdinBuf.WriteByte('^')
		stdinBuf.WriteString(ex)
		stdinBuf.WriteByte('\n')
	}

	args := []string{"pack-objects", "--revs", "--stdout", "-q"}
	if opt.UseOfsDelta {
		args = append(args, "--delta-base-offset")
	}

	cmd, stdout, stderr, err := startHardenedGitPipe(ctx, res.gitBinary, res.homeDir, res.RepoDir, &stdinBuf, args...)
	if err != nil {
		return CleanPackStats{}, domain.WrapError(domain.ErrInternal, "CLEAN_REPACK_FAILED", "failed starting git pack-objects", err)
	}

	hasher := sha256.New()
	cw := &countingWriter{}
	mw := io.MultiWriter(dst, hasher, cw)

	_, copyErr := io.Copy(mw, stdout)
	_ = stdout.Close()
	waitErr := cmd.Wait()

	if copyErr != nil {
		return CleanPackStats{}, domain.WrapError(domain.ErrInternal, "CLEAN_REPACK_FAILED", "failed streaming clean packfile", copyErr)
	}
	if waitErr != nil {
		return CleanPackStats{}, domain.Unprocessable("CLEAN_REPACK_FAILED", "git pack-objects failed: "+checkout.SanitizeGitOutput(stderr.String()))
	}

	hasObjs := len(res.Commits)+len(res.Trees)+len(res.Blobs)+len(res.Tags) > 0
	return CleanPackStats{
		BytesWritten: cw.n,
		PackSHA256:   hex.EncodeToString(hasher.Sum(nil)),
		HasObjects:   hasObjs,
	}, nil
}

// RepackForUpstream builds a clean packfile in memory for bounded upstream forwarding.
func RepackForUpstream(ctx context.Context, res *UnpackResult, opts ...CleanPackOptions) ([]byte, CleanPackStats, error) {
	var buf bytes.Buffer
	stats, err := BuildCleanPack(ctx, res, &buf, opts...)
	if err != nil {
		return nil, CleanPackStats{}, err
	}
	return buf.Bytes(), stats, nil
}
